                        foreach (Interval interval in dp[ii])
                        {
                            next[ii].Add(new Interval(interval.l, interval.r));
                            next[ii + 1].Add(new Interval(interval.l, interval.r + delta));
                            next[ii + 2].Add(new Interval(interval.l, interval.r + delta));
                        }
                    }
                }

                prev = r[i];
                for (int index = 0; index < dp.Length; index++)
                {
                    dp[index].Clear();

                    Interval pr = null;
                    foreach (Interval interval in next[index].OrderBy(t => t.l))
                    {
                        if (interval.l > n)
                            break;
                        if (pr != null && pr.r >= interval.l)
                        {
                            pr.r = Math.Max(pr.r, interval.r);
                        }
                        else
                        {
                            if (pr != null && !Find(dp, pr, index))
                                dp[index].Add(pr);
                            pr = interval;
                        }
                    }
                    if (pr != null && !Find(dp, pr, index))
                        dp[index].Add(pr);
                }
            }

            {
                int delta = 2*n - prev;
                for (int index = 0; index < dp.Length; index++)
                {
                    if (index%2 == 0)
                    {
                        List<Interval> t = dp[index];
                        foreach (Interval interval in t)
                        {
                            interval.l += delta;
                            interval.r += delta;
                        }
                    }
                }
            }

            for (int i = 0; i < dp.Length; i++)
            {
                foreach (Interval interval in dp[i])
                {
                    if (interval.l <= n && interval.r >= n)
                    {
                        writer.WriteLine("Full");
                        writer.WriteLine(i);
                        return;
                    }
                }
            }

            writer.WriteLine("Hungry");
        }


        private static bool Find(List<Interval>[] dp, Interval value, int index)
        {
            for (int i = index - 2; i >= 0; i--)
            {
                int ind = dp[i].BinarySearch(value, value);
                if (ind < 0)
                {
                    ind = (~ind) - 1;
                    if (ind > 0 && dp[i][ind].r >= value.r)
                    {
                        return true;
                    }
                }
                else
                {
                    if (dp[i][ind].r >= value.r)
                        return true;
                }
            }

            return false;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }

        #region Nested type: Interval

        private class Interval : IComparer<Interval>
        {
            public int l, r;

            public Interval(int l, int r)
            {
                this.l = l;
                this.r = r;
            }

            #region IComparer<Interval> Members

            public int Compare(Interval x, Interval y)
            {
                return x.l.CompareTo(y.l);
            }

            #endregion
        }

        #endregion
    }
